INSERT INTO 
	COMMU_COMMENT (

    SELECT
        'CMCM'||
        LPAD(NVL(TO_NUMBER(SUBSTR(MAX(COMMU_COMMENT_NO), LENGTH('CMCM' ) + 1)), 0) + 1, 6, '0')
    FROM 
    	COMMU_COMMENT

	  COMMU_COMMENT_NO
	, COMMU_POST_NO
	, AVATAR_ID
	, COMMU_COMMENT_CONTENT
	, COMMU_COMMENT_WRITE_DATE
	, COMMU_COMMENT_STATUS
) VALUES (
	  #{commuCommentNo}
	, #{commuPostNo}
	, #{avatarId}
	, #{commuCommentContent}
	, sysdate
	, #{commuCommentStatus}
)

